using Factorraria.Common.Machines;
using Terraria;
using Terraria.ID;
using Terraria.ModLoader;

namespace Factorraria.Common.Net
{
    // Entity bootstrap (roadmap patch 4.5). Machine entities used to be created lazily from draw code, which also covered vanilla
    // machine tiles generated by the world (Hellforges, furnaces in houses) and tiles placed before the entity system existed. Draw
    // code no longer creates anything (patch 4.2 for clients, this patch for single-player), so the process that owns the simulation
    // scans the world once after it loads and creates every missing entity.
    //
    // Authority: server and single-player only (a multiplayer client does nothing; it gets the entities from the server's tile-entity
    // sharing message 86, or with the vanilla section data when it joins later). The scan is chunked (ColumnsPerTick world columns per
    // tick) so a big world does not stall a tick; it starts on the first update after the world loads. Creation goes through
    // MachinePlacement.EnsureEntity, which is idempotent, so running over a machine twice, or racing with a placement, is harmless.
    // A bootstrapped machine keeps biome Unknown: nobody placed it, so no biome was reported (see patch 4.3).
    public class MachineBootstrapSystem : ModSystem
    {
        public static int ColumnsPerTick = 150;

        static bool scanning;
        static int nextColumn;
        static int created;
        static int machineTiles;
        static bool[] isMachineTile;

        public override void OnWorldLoad()
        {
            scanning = Main.netMode != NetmodeID.MultiplayerClient;
            nextColumn = 0;
            created = 0;
            machineTiles = 0;
            isMachineTile = null;
        }

        public override void OnWorldUnload()
        {
            scanning = false;
            isMachineTile = null;
        }

        public override void PostUpdateEverything()
        {
            if (!scanning)
                return;

            if (Main.netMode == NetmodeID.MultiplayerClient)
            {
                scanning = false;
                return;
            }

            if (isMachineTile == null)
            {
                isMachineTile = new bool[TileLoader.TileCount];
                foreach (int type in MachineVisualRegistry.Definitions.Keys)
                    if (type > 0 && type < isMachineTile.Length)
                        isMachineTile[type] = true;
            }

            int end = nextColumn + ColumnsPerTick;
            if (end > Main.maxTilesX)
                end = Main.maxTilesX;

            for (int x = nextColumn; x < end; x++)
            {
                for (int y = 0; y < Main.maxTilesY; y++)
                {
                    Tile tile = Main.tile[x, y];
                    if (!tile.HasTile || tile.TileType >= isMachineTile.Length || !isMachineTile[tile.TileType])
                        continue;

                    machineTiles++;

                    if (TileEntityHelper.TryGetEntityFromTile(x, y, out _, out _))
                        continue;

                    if (MachinePlacement.EnsureEntity(x, y) != null)
                        created++;
                }
            }

            nextColumn = end;

            if (nextColumn >= Main.maxTilesX)
            {
                scanning = false;
                FactorrariaNet.Log("[Machines] bootstrap scan done: " + machineTiles + " machine tile(s) seen, " + created + " entity(ies) created at their corner");
            }
        }
    }
}